import Emitter from './Emitter';

const makeSpy = () => {
  const fn = (...args) => { fn.calls.push(args); };
  fn.calls = [];
  return fn;
};

describe('Emitter', () => {
  test('calls listener when event is emitted', () => {
    const emitter = new Emitter();
    const spy = makeSpy();
    emitter.on('ping', spy);
    emitter.emit('ping', 'data');
    expect(spy.calls.length).toBe(1);
    expect(spy.calls[0]).toEqual(['data']);
  });

  test('removes listener correctly', () => {
    const emitter = new Emitter();
    const spy = makeSpy();
    emitter.on('ping', spy);
    emitter.emit('ping', 1);
    expect(spy.calls.length).toBe(1);
    emitter.off('ping', spy);
    emitter.emit('ping', 2);
    expect(spy.calls.length).toBe(1);
  });

  test('handles multiple listeners for same event', () => {
    const emitter = new Emitter();
    const a = makeSpy();
    const b = makeSpy();
    emitter.on('ping', a);
    emitter.on('ping', b);
    emitter.emit('ping', 42);
    expect(a.calls[0]).toEqual([42]);
    expect(b.calls[0]).toEqual([42]);
  });

  test('emit/off are no-op for unknown events/listeners', () => {
    const emitter = new Emitter();
    const spy = makeSpy();
    emitter.off('missing', spy);
    emitter.emit('missing', 123);
    expect(spy.calls.length).toBe(0);
  });
});

