    const latest = takeLatest((signal, value: string, ms: number) => delay(ms, value, signal));

    const p1 = latest('first', 30);
    const p2 = latest('second', 5);

    await expect(p1).rejects.toMatchObject({ name: 'AbortError' });
    await expect(p2).resolves.toBe('second');
  });

  it('propagates errors from the latest call', async () => {
    const latest = takeLatest(async () => {
      throw new Error('boom');
    });

    await expect(latest()).rejects.toThrow('boom');
  });

  it('does not abort a controller after its call has completed', async () => {
    const signals: AbortSignal[] = [];
    const latest = takeLatest(async (signal, value: string) => {
      signals.push(signal);
      return value;
    });

    await expect(latest('first')).resolves.toBe('first');
    const completedSignal = signals[0];
    await expect(latest('second')).resolves.toBe('second');

    expect(completedSignal.aborted).toBe(false);
  });

  it('a stale finally cannot clear the newer in-flight controller', async () => {
    const runs: Array<{ signal: AbortSignal; value: string; resolve: (value: string) => void }> = [];
    const latest = takeLatest((signal, value: string) => new Promise<string>((resolve) => {
      runs.push({ signal, value, resolve });
    }));

    const first = latest('first');
    await Promise.resolve();
    const second = latest('second');
    await Promise.resolve();

    runs[0].resolve('first');
    await expect(first).rejects.toMatchObject({ name: 'AbortError' });

    const third = latest('third');
    await Promise.resolve();
    expect(runs[1].signal.aborted).toBe(true);

    runs[1].resolve('second');
    runs[2].resolve('third');
    await expect(second).rejects.toMatchObject({ name: 'AbortError' });
    await expect(third).resolves.toBe('third');
  });

  it('aborts the previous controller immediately', async () => {
    const latest = takeLatest((signal) => delay(20, 'ok', signal));

    const p1 = latest();
    await new Promise((r) => setTimeout(r, 1));
    const p2 = latest();

    await expect(p1).rejects.toMatchObject({ name: 'AbortError' });
    await expect(p2).resolves.toBe('ok');
  });
});

